CREATE TABLE [dbo].[RIA_FORMACALIF](	  [id_forma] INT NOT NULL IDENTITY(1,1)	, [fecha_calif] SMALLDATETIME NOT NULL	, [id_calificador] INT NOT NULL	, [id_supervisor] INT NOT NULL	, [id_grabacion] BIGINT NOT NULL	, [id_formato] INT NOT NULL	, [total_forma] INT NULL DEFAULT((0))	, [age_id] INT NOT NULL	, [version] INT NOT NULL	, [tipo] SMALLINT NOT NULL DEFAULT((0))	, [tipo_llamada] SMALLINT NOT NULL DEFAULT((0))	, [cam_id] SMALLINT NOT NULL DEFAULT((0))	, CONSTRAINT [PK_TREC_FORMACALIF] PRIMARY KEY ([id_forma] ASC))